INSERT INTO `oas_memos` VALUES (1,'Instruksi Pemeliharaan Infrastruktur Server & Cloud Backup Rutin','Chief Technology Officer (CTO)','Seluruh Tim DevOps & Database Administrator','Information Technology','urgent','Sehubungan dengan peningkatan volume transaksi e-commerce, seluruh unit server akan menjalankan snapshot backup otomatis setiap pukul 02:00 WIB. Pastikan database replica tetap tersinkronisasi tanpa latensi.','Memo Operasional','2026-09-14 06:40:36','2026-09-14 06:40:36'),(2,'Kebijakan Standarisasi Pengemasan Barang Sensitif & Hardware High-End','Kepala Divisi Logistik & Gudang','Staf Operasional Fulfillment','Logistics & Supply Chain','normal','Setiap pengiriman laptop, kamera mirrorless, dan komponen PC wajib menggunakan pelindung bantalan udara (bubble wrap) 5 lapis serta segel lakban anti-tamper berlogo APEX.','Standard Operating Procedure','2026-09-14 06:40:36','2026-09-14 06:40:36'),(3,'Pengumuman Pencapaian Target Penjualan Kuartal I Tahun 2026','Direktur Utama','Seluruh Karyawan & Divisi MSI','Executive Office','normal','Kami mengapresiasi kerja keras seluruh tim atas tercapainya omzet penjualan retail melampaui Rp 350.000.000,- pada periode awal tahun 2026. Program insentif performa akan disalurkan akhir bulan ini.','Surat Edaran','2026-09-14 06:40:36','2026-09-14 06:40:36'),(4,'Protokol Keamanan Data Pelanggan & Enkripsi Kata Sandi','Information Security Lead','Pengembang Aplikasi & Web Engineer','Cybersecurity','confidential','Seluruh kata sandi pengguna wajib menggunakan hashing standar industri Bcrypt rounds 12. Larangan keras mencatat plaintext password pada file logging atau kanal publik apa pun.','Instruksi Keamanan','2026-09-14 06:40:36','2026-09-14 06:40:36'),(5,'Jadwal Stock Opname & Audit Inventaris Komponen Triwulan II','Internal Audit Team','Supervisor Gudang Utama Yogyakarta','Finance & Audit','normal','Pelaksanaan stock opname fisik terhadap prosesor, VGA, dan SSD akan diselenggarakan pada hari Sabtu mendatang. Mohon siapkan lembar pencatatan barcode scanner.','Pemberitahuan Audit','2026-09-14 06:40:36','2026-09-14 06:40:36'),(6,'Rencana Peluncuran Program Garansi Ganti Baru 14 Hari','Head of Customer Relations','Tim Layanan Pelanggan & Aftersales','Customer Care','normal','Mulai tanggal 1 bulan depan, APEX Store memberlakukan program jaminan tukar baru untuk unit dengan cacat pabrik dalam kurun 14 hari kerja sejak barang diterima pembeli.','Memo Kebijakan','2026-09-14 06:40:36','2026-09-14 06:40:36'),(7,'Pengadaan Lisensi Software Monitoring Performa Server','Lead Infrastructure Engineer','Bagian Pengadaan & Purchasing','Procurement','normal','Pengajuan perpanjangan langganan monitoring APM Datadog dan sentry error tracking untuk cluster server aplikasi e-commerce periode tahunan.','Formulir Permohonan','2026-09-14 06:40:36','2026-09-14 06:40:36'),(8,'Penyesuaian Jam Operasional Ekspedisi Pengiriman Selama Libur Nasional','Manajer Operasional','Seluruh Pelanggan & Mitra Kurir','Operational Management','urgent','Pengiriman reguler akan mengalami jeda 1 hari saat tanggal merah libur nasional. Layanan Instant Courier (Gojek/Grab) tetap melayani pesanan di wilayah Jabodetabek dan DIY.','Surat Pemberitahuan','2026-09-14 06:40:36','2026-09-14 06:40:36');
/*!40000 ALTER TABLE `oas_memos` ENABLE KEYS */;
