/*!50003 CREATE*/ /*!50017 DEFINER=`msi_user`@`%`*/ /*!50003 TRIGGER `after_orders_insert` AFTER INSERT ON `orders` FOR EACH ROW BEGIN
                INSERT INTO logs (user_id, action, ip_address, created_at)
                VALUES (
                    NEW.user_id,
                    CONCAT('Pesanan Baru Masuk #', NEW.order_number, ' - Rp ', FORMAT(NEW.total_amount, 0)),
                    '127.0.0.1',
                    NOW()
                );
            END */;;
DELIMITER ;
