DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`msi_user`@`%`*/ /*!50003 TRIGGER `after_orders_status_update` AFTER UPDATE ON `orders` FOR EACH ROW BEGIN
                IF OLD.status != NEW.status THEN
                    INSERT INTO logs (user_id, action, ip_address, created_at)
                    VALUES (
                        NEW.user_id,
                        CONCAT('Status Pesanan #', NEW.order_number, ' Diperbarui: ', UPPER(OLD.status), ' -> ', UPPER(NEW.status)),
                        '127.0.0.1',
                        NOW()
                    );
                END IF;
            END */;;
DELIMITER ;
